function studioBookings(bookings) {
  let best = 0;
  for (const [t] of bookings) {
    let busy = 0;
    for (const [start, end] of bookings) if (start <= t && t < end) busy++;
    best = Math.max(best, busy);
  }
  return best;
}

function studioBookings(bookings) {
  const starts = bookings.map((b) => b[0]).sort((a, b) => a - b);
  const ends = bookings.map((b) => b[1]).sort((a, b) => a - b);
  let open = 0, best = 0, j = 0;
  for (const start of starts) {
    while (j < ends.length && ends[j] <= start) { j++; open--; }
    open++;
    best = Math.max(best, open);
  }
  return best;
}
